def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 r=json.loads((OUT/'report.json').read_text(encoding='utf-8'));a=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8'));assert a['passed'] and a['report_sha256']==sha(OUT/'report.json') and not r['preliminary_gate'];g=r['groups'];n=g['1.0'];w=g['0.25'];refs=['runs/flyvis_equal_readout_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json')]
 msg=(f"На четырёх других, но ранее изученных в проекте сценах для штатной модели после разворота при слабом контрасте ошибка линейного считывателя двух фиксированных комбинаций T4/T5 составила {w['stock_projected']['after_epe']:.4f}, а считывателя двух выходов штатного декодера — {w['stock_decoder']['after_epe']:.4f}; у обоих по четыре настраиваемых по цели коэффициента. Три последовательных правильных знака найдены в {w['stock_projected']['latency_identified']}/16 и {w['stock_decoder']['latency_identified']}/16 зависимых условиях соответственно; средняя задержка корректно определена только для декодера: {w['stock_decoder']['latency_mean']:.4f} кадра. При обычном контрасте ошибка составила {n['stock_projected']['after_epe']:.4f} против {n['stock_decoder']['after_epe']:.4f}; три правильных знака найдены в {n['stock_projected']['latency_identified']}/16 против {n['stock_decoder']['latency_identified']}/16. Признак T4/T5 с восемью входами, отдельно и не равной сложности, дал при слабом контрасте {w['stock_all8']['after_epe']:.4f} и {w['stock_all8']['latency_identified']}/16. Фазовая корреляция без FlyVis на искусственном общем сдвиге дала {w['phase']['after_epe']:.4f} и {n['phase']['after_epe']:.4f}. Критерий 10% выигрыша и полной задержки не пройден ни в одной из четырёх групп по версии и контрасту.")
 limit=('Оба основных считывателя имели по два входа и четыре обучаемых по целевой скорости коэффициента; фиксированная заранее проекция восьми групп T4/T5 в два числа могла отбросить полезную информацию. Декодер дополнительно линейно настроен, а не представлен штатным выходом без изменений. Восемь сцен настройки и четыре оценки не пересекаются, но все сцены ранее изучались в проекте и взяты из обучающего набора BDD. Условия внутри четырёх сцен зависимы. Пространственные активности усреднены; причинное выключение групп и реальный трекер не проверялись. HOTA нет. Несработавший критерий не опровергает всю FlyVis.')
 (OUT/'РЕЗУЛЬТАТ.md').write_text('# Считыватели с двумя входами на других сценах\n\n'+msg+'\n\n'+limit+'\n\nИсточники: '+', '.join('`'+x+'`' for x in refs)+'.\n',encoding='utf-8')
 cat=ROOT/'experiments/project_history.json';d=json.loads(cat.read_text(encoding='utf-8'));c=next(x for x in d['experiments'] if x['id']=='flyvis_equal_readout_v1');assert c['state']=='planned';c.update(state='completed_negative',done=datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat(),obtained=msg+' Источники: '+', '.join(refs),interpretation='Предварительный выигрыш по EPE не достиг заданного порога и сопровождался отсутствием определённого разворота в части случаев. Двухмерная проекция может терять информацию, потому причина и общий потенциал ядра не установлены.',decision='Не принимать фиксированную двухмерную проекцию как решение; сохранить 8-входовой результат отдельно с ограничениями.',cannot_claim=limit);c['acceptance'][0].update(met=False,evidence=refs[1]+':checks; '+refs[2]);c['evidence'] += [dict(kind='json',ref=x,claim='Результат и повторный пересчёт') for x in refs[1:]];cat.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 prob=ROOT/'experiments/system_problems.json';d=json.loads(prob.read_text(encoding='utf-8'));item=next(x for x in d['problems'] if x['id']=='С7');item['cases'].append(dict(date='2026-11-05',fact=msg+' '+limit,evidence=refs));item['cards'].append(c['id'])
 for x in refs:item['evidence'].append(dict(source=x,sha256=sha(ROOT/x),claim='Сравнение двухвходовых считывателей на других сценах'))
 prob.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 plan=ROOT/'dissertation/ЕДИНЫЙ_ПЛАН.md';raw=plan.read_bytes();marker='## Журнал изменений'.encode();nl=b'\r\n' if marker+b'\r\n' in raw else b'\n';now=datetime.now(ZoneInfo('Europe/Moscow'));entry=f'\n**{now:%d.%m.%Y, %H:%M} MSK** — Равное число входов считывателей FlyVis\n\n{msg} {limit} Источники: '+', '.join('`'+x+'`' for x in refs)+'. С7 остаётся открытой.\n\n';assert raw.count(marker+nl)==1;plan.write_bytes(raw.replace(marker+nl,marker+nl+entry.encode(),1))
 with (ROOT/'FLYVIS_TRACKER_RESEARCH_ROADMAP.md').open('a',encoding='utf-8') as f:f.write('\n\n## 05.11.2026 — равное число входов считывателей\n\n'+msg+' '+limit+' Источник: `'+refs[1]+'`. С7 открыта.\n')
 vault=ROOT/'ObsidianFlyVis';stage=OUT/'vault_checked';backup=OUT/'vault_before';assert not stage.exists() and not backup.exists();shutil.copytree(vault,stage);shutil.copytree(vault,backup);before={f.relative_to(vault).as_posix():sha(f) for f in vault.rglob('*') if f.is_file()};name=problem_path(next(x for x in load()['problems'] if x['id']=='С7'))+'.md';preserve=[x for x in before if x.endswith('.md') and x!=name];assert build(stage,preserve)==0
 for f in ('.obsidian/graph.json','.graph-visible.json','.generated.json'):shutil.copy2(backup/f,stage/f)
 check=audit(stage);assert check['note_count']==55 and check['hypothesis_node_count']==25 and check['problem_node_count']==10 and not check['external_hypothesis_edges'];assert set(before)=={f.relative_to(stage).as_posix() for f in stage.rglob('*') if f.is_file()};changed=[f for f,h in before.items() if sha(stage/f)!=h];assert changed==[name] and all(sha(vault/f)==h for f,h in before.items());shutil.copy2(stage/name,vault/name);done=audit(vault);assert done['hashes']==check['hashes'];done.update(changed_files=changed,added_files=[],deleted_files=[],protected_hypotheses_byte_exact=True);(OUT/'graph_audit.json').write_text(json.dumps(done,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Recorded and graph checked')
if __name__=='__main__':main()
